use std::rc::Rc;use std::cell::RefCell;use std::collections::VecDeque;impl Solution{pub fn zigzag_level_order(root:Option<Rc<RefCell<TreeNode>>>)->Vec<Vec<i32>>{let mut o=vec![];let mut q=VecDeque::new();if let Some(r)=root{q.push_back(r)}else{return o}let mut rev=false;while !q.is_empty(){let n=q.len();let mut v=vec![0;n];for i in 0..n{let x=q.pop_front().unwrap();let b=x.borrow();v[if rev{n-1-i}else{i}]=b.val;if let Some(l)=b.left.clone(){q.push_back(l)}if let Some(r)=b.right.clone(){q.push_back(r)}}o.push(v);rev=!rev;}o}}
